CREATE TABLE public.qa_baseline_functions AS SELECT n.nspname,p.proname,pg_get_function_identity_arguments(p.oid) args,pg_get_functiondef(p.oid) definition,p.proowner,p.proacl FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN ('aurea_private','aurea_delivery_rpc') AND p.proname IN ('manager_publications_v2','pulse_summary','delivery_publications','impl_delivery_publications','persist_weekly_digest','impl_persist_weekly_digest');
DO $$ BEGIN IF (SELECT count(*) FROM public.qa_baseline_functions)<>6 THEN RAISE EXCEPTION 'baseline count'; END IF; END $$;
